#define time iTime
#define Pi 3.1415926535
#define Pi2 (Pi*2.)
#define resolution iResolution

float bpm = 141.;

// Modified palette for pastel colors:
vec3 palette( float t ) {
    // "a" is the base (light) color and "b" is the amplitude (reduced for pastels)
    vec3 a = vec3(0.8, 0.8, 0.8);
    vec3 b = vec3(0.8, 0.8, 0.8);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.9, 0.33, 0.67);
    return a + b * cos( 6.28318 * (c * t + d) );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Slow down the overall animation by a factor of 10.
    float slowTime = time * 0.02;

    // Use slowTime instead of time everywhere:
    float depth = slowTime / 10.0;
    float zoom = 8.0;

    vec2 uv = (fragCoord.xy / 2.0 - resolution.xy) / resolution.y;
    uv /= zoom;
    vec2 uv0 = uv;
    vec3 color = vec3(0.0);

    float angle = depth * 2.0;
    for (float j = 0.0; j < zoom; ++j) {
        uv = fract(uv * 2.0) - 0.5;
        uv *= mat2(cos(angle), -sin(angle), sin(angle), cos(angle));

        // Also using slowTime here to slow down the oscillation:
        float d = smoothstep(0.0, 0.15, abs(sin(length(uv) * 8.0 + slowTime) / 8.0));
        d = 0.02 / d;

        vec3 col = palette(length(uv * j));
        col *= palette(length(uv0 * j));
        color += col * d;
    }

    fragColor = vec4(color, 1.0);
}
